Q: PHP 5 constructor _construct() is not executed by class instantiation A: <p><a href="https://www.php.net/manual/en/language.oop5.decon.php" rel="nofollow noreferrer">Constructor methods</a> begin with two underscores. This is consistent across all PHP's &quot;<a href="https://www.php.net/manual/en/language.oop5.magic.php" rel="nofollow noreferrer">Magic Methods</a>&quot;. Use:</p>
<pre class="lang-php prettyprint-override"><code>abstract class Foo
{
    function __construct() {} 
}

class Bar extends Foo
{
    function __construct($arg)
    {
        parent::_construct();
    } 
}
</code></pre>

Q: How can I implement Java-like enums in Go? A: <p>Usage demonstrates:</p>
<ol>
<li><p>singleton identity (<code>==</code>)</p>
</li>
<li><p>natural <code>switch</code></p>
</li>
<li><p>efficient lookup</p>
</li>
<li><p>per-constant state</p>
</li>
</ol>
<pre class="lang-golang prettyprint-override"><code>// Identity comparison (compares underlying shared reference)
if notification.Type == notificationType.Progress {
    ...
}

// Switch
switch notification.Type {
case notificationType.Message:
    ...
case notificationType.Progress:
    ...
default:
    panic(&quot;unknown notification type&quot;)  
}

// Name and ordinal
fmt.Println(notification.Type.Name())    // &quot;Progress&quot;
fmt.Println(notification.Type.Ordinal()) // 1

// Lookup by name
t := notificationType.Enum.ValueOf(&quot;Progress&quot;)

// Lookup by ordinal
t := notificationType.Enum.ValueOfOrdinal(1)

// Enumerate all values
for _, t := range notificationType.Enum.Values() {
    fmt.Println(t.Name())
}

// Additional state
fmt.Println(t.DisplayName())
</code></pre>
<p><em><strong>NotificationType</strong></em> definition</p>
<pre class="lang-golang prettyprint-override"><code>package notificationType

var Message = newNotificationType(&quot;Message&quot;, &quot;Message display name&quot;)
var Progress = newNotificationType(&quot;Progress&quot;, &quot;Progress display name&quot;)

var Enum = enum.NewEnum(
    Message,
    Progress,
)

type NotificationType struct {
    enum.EnumValue[NotificationType]
}

func newNotificationType(name, displayName string) NotificationType {
    return NotificationType{
        EnumValue: enum.NewEnumValue[NotificationType](name, displayName),
    }
}

func (this NotificationType) DisplayName() string {
    return this.Property(0).(string)
}

func (this NotificationType) MarshalJSON() ([]byte, error) {
    return json.Marshal(this.Name())
}

func (this *Color) UnmarshalJSON(data []byte) error {
    var name string
    if err := json.Unmarshal(data, &amp;name); err != nil {
        return err
    }
    *this = RGB.ValueOf(name)
    return nil
}
</code></pre>
<p><em><strong>Enum.go</strong></em></p>
<pre class="lang-golang prettyprint-override"><code>package enum

import &quot;github.com/go-jang/go/lang&quot;

type value[T any] interface {
    Name() string
    setOrdinal(int)
    setDescriptor(*Enum[T])
}

type Enum[T any] struct {
    byName    map[string]T
    byOrdinal []T
}

func NewEnum[T value[T]](values ...T) *Enum[T] {
    d := &amp;Enum[T]{
        byName:    make(map[string]T, len(values)),
        byOrdinal: make([]T, len(values)),
    }
    for i, value := range values {
        value.setOrdinal(i)
        value.setDescriptor(d)
        if _, exists := d.byName[value.Name()]; exists {
            panic(&quot;Duplicate enum constant: &quot; + value.Name())
        }
        d.byName[value.Name()] = value
        d.byOrdinal[i] = value
    }
    return d
}

func (this *Enum[T]) ValueOf(name string) T {
    v, ok := this.byName[name]
    lang.Assert(ok, &quot;No enum constant %T.%s&quot;, this, name)
    return v
}

func (this *Enum[T]) ValueOfOrdinal(ordinal int) T {
    lang.Assert(ordinal &gt;= 0 &amp;&amp; ordinal &lt; len(this.byOrdinal), &quot;Invalid ordinal %T: %d&quot;, this, ordinal)
    return this.byOrdinal[ordinal]
}

func (this *Enum[T]) Values() []T {
    return append([]T(nil), this.byOrdinal...)
}
</code></pre>
<p><em><strong>EnumValue.go</strong></em></p>
<pre class="lang-golang prettyprint-override"><code>package enum

func ValueOf[T any](d *Enum[T], name string) T {
    return d.ValueOf(name)
}

func ValueOfOrdinal[T any](d *Enum[T], ordinal int) T {
    return d.ValueOfOrdinal(ordinal)
}

func ValuesOf[T any](d *Enum[T]) []T {
    return d.Values()
}

type enumValue[T any] struct {
    enum       *Enum[T]
    name       string
    ordinal    int
    properties []any
}

type EnumValue[T any] struct {
    value *enumValue[T]
}

func NewEnumValue[T any](name string, properties ...any) EnumValue[T] {
    return EnumValue[T]{
        value: &amp;enumValue[T]{
            name:       name,
            ordinal:    -1,
            properties: properties,
        },
    }
}

func (this EnumValue[T]) Name() string {
    return this.value.name
}

func (this EnumValue[T]) Ordinal() int {
    return this.value.ordinal
}

func (this EnumValue[T]) Enum() *Enum[T] {
    return this.value.enum
}

func (this EnumValue[T]) Property(index int) any {
    return this.value.properties[index]
}

func (this EnumValue[T]) String() string {
    return this.value.name
}

func (this EnumValue[T]) setOrdinal(ordinal int) {
    this.value.ordinal = ordinal
}

func (this EnumValue[T]) setDescriptor(descriptor *Enum[T]) {
    this.value.enum = descriptor
}
</code></pre>

Q: React Native, &#39;is not usable as a native method argument&#39; A: <p>I encountered this issue while using Axios with formData field without converting the appended data to string format.</p>
<p>Gives errors:</p>
<pre><code>const formData = new FormData();
formData.append(&lt;field_name&gt;, field_data);
</code></pre>
<p>Must be in the form:</p>
<pre><code>const formData = new FormData();
formData.append(&lt;field_name&gt;, JSON.stringify(field_data));
</code></pre>

Q: !permit command for Twitch, mIRC/mSL A: <p>first, your bot needs to be opped on channel</p>

<p>if someone that is not on permit or alwayspermit list post a link they will get kicked</p>

<p>seconds, press alt+r click "file" then "new" in there paste this code</p>

<pre><code>on $@*:text:*:#:{
if ($regex($1-,/(http\72\/\/|www\.).+\.(com|co|uk)/iS)) &amp;&amp; ($nick !isop $chan) {
if (!$istok(%permit,$nick,32)) {
  kick $nick $chan You dont have permission to post links in here 
}
}
noop $regex($1-,/^!(del|alwayspermit|permit)\s(\S+)/iS) { 
if ($regml(1) == alwayspermit) &amp;&amp; ($nick isop $chan) {
  if ($istok(%permit,$regml(2),32)) {
    msg $chan $regml(2) is already on always permit list
  }
  else {
    set %permit $addtok(%permit,$regml(2),32)
    msg $chan $regml(2) You are now always permited to post links
  }
 }
 if ($regml(1) == permit) &amp;&amp; ($nick isop $chan) {
  set %permit $addtok(%permit,$regml(2),32)
  .timerunset 1 20 set %permit $remtok(%permit,$regml(2),1,32)
  msg $chan $regml(2) You have 20 seconds to post a link in here
 }
 if ($regml(1) == del) &amp;&amp; ($nick isop $chan) {
  if ($istok(%permit,$regml(2),32)) {
    set %permit $remtok(%permit,$regml(2),1,32)
    msg $chan $regml(2) erased suceffully from always permit list
  }
  else {
    msg $chan $regml(2) is not on always permit list
  }
 }
 }
 }
</code></pre>

<p>commands:</p>

<p>!permit nick
will add a permitted nick for 20 seconds</p>

<p>!alwayspermit nick
will add a permitted nick permanent </p>

<p>!del nick
will delete a nick from permitted list</p>

Q: White blob detection A: <p>if you want to get a marked blob you can use this code </p>

<pre><code>public void DetectBigBlobs(Bitmap bitmap)
    {
        BlobCounter blobCounter = new BlobCounter();

        Graphics g = Graphics.FromImage(bitmap);

        //filtering the blobs before searching for blobs 
        blobCounter.FilterBlobs = true;
        blobCounter.MinHeight = bitmap.Height/3;
        blobCounter.MinWidth = bitmap.Width/3;

        blobCounter.ProcessImage(bitmap);
        Blob[] blobs = blobCounter.GetObjectsInformation();

        foreach (Blob b in blobs)
        { 
            //getting the found blob edgepoints 
            List&lt;IntPoint&gt; edgePoints = blobCounter.GetBlobsEdgePoints(b);
            //if you want to mark every edge point RED 
            foreach (IntPoint point in edgePoints)
                bitmap.SetPixel(point.X, point.Y, Color.Red);
            //if you want to draw a rectangle around the blob 
            g.DrawRectangle(Pens.Blue,b.Rectangle);

        }

        g.Dispose();
    }
</code></pre>

